from PIL import Image
import numpy as np
im = np.array(Image.open('mol_0094.png').convert('L'))
bw = im < 128
for y in range(240,470,10):
    xs = [x for x in range(520,700) if bw[y,x]]
    groups=[]
    for x in xs:
        if groups and x-groups[-1][-1]<=2: groups[-1].append(x)
        else: groups.append([x])
    print(y, [(g[0],g[-1]) for g in groups])
